@dataclass(frozen=True, kw_only=True)
class LogEntry:
    """One kept event."""

    # When it happened, Unix ms.
    at: int
    # Its network's chain; always present, null: no network's.
    chain: str | None
    # Its fields and its spans' (`network`, `node`, …), as text.
    fields: dict[str, str]
    # Its id, newest highest: given as it is kept, so the same on the live
    # stream (`/v1/logs/stream`) as stored.
    id: int
    # The job it ran in; always present, null: none.
    job_id: int | None
    # `error`, `warn`, `info`, `debug` or `trace`.
    level: str
    # The market it concerns (`binance`, …); always present, null: none.
    market: str | None
    # The event's own message, in place of its template; always present,
    # null: none, the template's.
    message: str | None
    # Its network's name; always present, null: no network's.
    network: str | None
    # The event's code: `rpc.http.failed`, `index.step`, … Its message is
    # its template (`GET /v1/logs/messages`) filled from `fields`.
    target: str
    # The transaction it concerns (`{chain}.{network}.{txid}`); always
    # present, null: none.
    transaction_id: str | None
    # The trigger it concerns; always present, null: none.
    trigger_id: str | None
    # The wallet it concerns (`{chain}.{network}.{address}`); always
    # present, null: none.
    wallet_id: str | None

    @classmethod
    def from_json(cls, data: Any) -> LogEntry:
        return cls(
            at=data["at"],
            chain=data["chain"],
            fields=data["fields"],
            id=data["id"],
            job_id=data["job_id"],
            level=data["level"],
            market=data["market"],
            message=data["message"],
            network=data["network"],
            target=data["target"],
            transaction_id=data["transaction_id"],
            trigger_id=data["trigger_id"],
            wallet_id=data["wallet_id"],
        )

    def to_json(self) -> dict[str, Any]:
        return {
            "at": self.at,
            "chain": self.chain,
            "fields": self.fields,
            "id": self.id,
            "job_id": self.job_id,
            "level": self.level,
            "market": self.market,
            "message": self.message,
            "network": self.network,
            "target": self.target,
            "transaction_id": self.transaction_id,
            "trigger_id": self.trigger_id,
            "wallet_id": self.wallet_id,
        }


