@dataclass(frozen=True, kw_only=True)
class SessionRead:
    """The caller's session, decoded and checked."""

    # How its login proved who it is (`pwd` or `passphrase`, then `otp`);
    # empty for a key's.
    amr: list[Amr]
    # Unix seconds; a key's bearer secret: now.
    expires_at: int
    # Unix seconds.
    issued_at: int
    # Its key, when a key issued it.
    key: UserKey | None = None
    # Who issued it.
    kind: Issuer
    # What it may do, packed.
    scopes: dict[str, list[str]]
    # Who it is for; always present, null: not said.
    sub: str | None
    # Its user.
    user: User

    @classmethod
    def from_json(cls, data: Any) -> SessionRead:
        return cls(
            amr=array(Amr, data["amr"]),
            expires_at=data["expires_at"],
            issued_at=data["issued_at"],
            key=optional(UserKey.from_json, data.get("key")),
            kind=Issuer(data["kind"]),
            scopes=data["scopes"],
            sub=data["sub"],
            user=User.from_json(data["user"]),
        )

    def to_json(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "amr": self.amr,
            "expires_at": self.expires_at,
            "issued_at": self.issued_at,
            "kind": self.kind,
            "scopes": self.scopes,
            "sub": self.sub,
            "user": encode(self.user),
        }
        if self.key is not None:
            data["key"] = encode(self.key)
        return data


