@dataclass(frozen=True, kw_only=True)
class Transaction:
    """A kept transaction: its `transaction` row and its kept legs. The API
    shows it as is. Read in one query: its legs come as a JSON array SQLite
    builds (`legs`).
    """

    # Its block; null while pending.
    block: str | None = None
    # Unix ms this server recorded it, before its first broadcast: set
    # exactly on this server's sends, mined or not; null on every other.
    # Mining keeps it.
    broadcasted_at: int | None = None
    chain: str
    # `{chain}.{network}.{txid}`.
    id: str
    # Its kept legs, in order.
    legs: list[Leg]
    network: str
    # Its position in its block; null while pending.
    order: int | None = None
    # Its block's position; null while pending.
    position: int | None = None
    # Why it reverted, when the chain said (`reverted`); null otherwise.
    # Stored as JSON, shown decoded.
    reason: str | None = None
    # 0 pending, 1 succeeded, 2 reverted.
    state: int
    # Chain-native transaction id.
    txid: str

    @classmethod
    def from_json(cls, data: Any) -> Transaction:
        return cls(
            block=data.get("block"),
            broadcasted_at=data.get("broadcasted_at"),
            chain=data["chain"],
            id=data["id"],
            legs=array(Leg.from_json, data["legs"]),
            network=data["network"],
            order=data.get("order"),
            position=data.get("position"),
            reason=data.get("reason"),
            state=data["state"],
            txid=data["txid"],
        )

    def to_json(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "chain": self.chain,
            "id": self.id,
            "legs": encode(self.legs),
            "network": self.network,
            "state": self.state,
            "txid": self.txid,
        }
        if self.block is not None:
            data["block"] = self.block
        if self.broadcasted_at is not None:
            data["broadcasted_at"] = self.broadcasted_at
        if self.order is not None:
            data["order"] = self.order
        if self.position is not None:
            data["position"] = self.position
        if self.reason is not None:
            data["reason"] = self.reason
        return data


